import { createRoot } from "react-dom/client"
// import ReactDOM from "react-dom"

import "./index.css"
import { goToChapter } from "./store"
import App from "./App"
import { ContentProvider, fetchContent } from "./common/content"

const reactRootContainer = "root"

async function init() {
  try {
    const content = await fetchContent("./content.json")

    const container = document.getElementById(reactRootContainer)
    const root = createRoot(container)

    goToChapter(1)

    root.render(
      <ContentProvider content={content}>
        <App />
      </ContentProvider>
    )

    /*     ReactDOM.render(
      <ContentProvider content={content}>
        <App />
      </ContentProvider>,
      document.getElementById(reactRootContainer)
    ) */
  } catch (err) {
    console.error(err)

    const container = document.getElementById(reactRootContainer)
    const root = createRoot(container)
    root.render(
      <div className="error">
        <p>App Loading Error</p>
      </div>
    )

    /*     ReactDOM.render(
      <div className="error">
        <p>App Loading Error</p>
      </div>,
      document.getElementById(reactRootContainer)
    ) */
  }
}

init()
